11	export function PropertiesPanel({ nodes, onNodeDataChange }: PropertiesPanelProps) {
12	  const selectedNodeId = useDesignerStore((state) => state.selectedNodeId);
13	  const nodeTypes = useDesignerStore((state) => state.nodeTypes);
14	
15	  const selectedNode = nodes.find((n) => n.id === selectedNodeId);
16	  const nodeType = selectedNode ? nodeTypes.find((t) => t.key === selectedNode.data?.key) : null;
17	
18	  const [localConfig, setLocalConfig] = useState<Record<string, unknown>>(() => {
19	    return (selectedNode?.data?.config as Record<string, unknown>) || {};
20	  });
21	  const [prevNodeId, setPrevNodeId] = useState<string | null>(selectedNodeId);
22	
23	  if (selectedNodeId !== prevNodeId) {
24	    setPrevNodeId(selectedNodeId);
25	    setLocalConfig((selectedNode?.data?.config as Record<string, unknown>) || {});
26	  }
27	
28	  const handleConfigChange = useCallback((key: string, value: string) => {
29	    if (!selectedNode) return;
30	    const newConfig = { ...localConfig, [key]: value };
31	    setLocalConfig(newConfig);
32	    onNodeDataChange(selectedNode.id, { ...selectedNode.data, config: newConfig });
33	  }, [selectedNode, localConfig, onNodeDataChange]);
34	
35	  useEffect(() => {
36	    const handleMessage = (event: MessageEvent) => {
37	      if (event.data?.type === 'oauth-success') {
38	        const properties = nodeType?.configSchema?.properties as Record<string, unknown> | undefined;
39	        const currentKey = Object.keys(properties || {}).find(
40	          k => (properties![k] as Record<string, unknown>)['x-connectorKey']
