52	    return (
53	      <aside className="w-80 bg-white border-l border-gray-200 p-4 h-full shadow-sm z-10 flex flex-col">
54	        <div className="text-gray-500 text-sm italic text-center mt-10">
55	          Select a node to view its properties.
56	        </div>
57	      </aside>
58	    );
59	  }
60	
61	  const handleConnect = async () => {
62	    try {
63	      const res = await apiClient.get('/api/integrations/google/auth');
