77	      return (
78	        <div key={key} className="space-y-1.5">
79	          <label className="block text-sm font-medium text-gray-700 capitalize">
80	            {key.replace(/_/g, ' ')}
81	          </label>
82	          <button
83	            className="w-full bg-blue-50 text-blue-600 border border-blue-200 rounded-md py-2 text-sm font-medium hover:bg-blue-100 transition-colors"
84	            onClick={() => handleConnect()}
85	          >
86	            Connect {schema['x-connectorKey'] as string}
87	          </button>
88	          {value && <div className="text-xs text-green-600 mt-1">✓ Connected</div>}
89	        </div>
90	      );
91	    }
92	
93	    // 2. Enum Dropdown
94	    if (schema.enum && Array.isArray(schema.enum)) {
95	      return (
96	        <div key={key} className="space-y-1.5">
97	          <label className="block text-sm font-medium text-gray-700 capitalize">
98	            {key.replace(/_/g, ' ')}
99	          </label>
100	          <select
101	            className="w-full border border-gray-300 rounded-md p-2 text-sm focus:ring-blue-500 focus:border-blue-500 bg-white"
102	            value={value}
103	            onChange={(e) => handleConfigChange(key, e.target.value)}
104	          >
105	            <option value="" disabled>Select {key}</option>
106	            {schema.enum.map((opt: string) => (
107	              <option key={opt} value={opt}>{opt}</option>
108	            ))}
109	          </select>
110	        </div>
111	      );
112	    }
