export interface WorkflowNode {
  id: string;
  data: { key: string; config?: unknown; [key: string]: unknown };
  [key: string]: unknown;
}

export interface WorkflowEdge {
  source: string;
  target: string;
  [key: string]: unknown;
}

export interface WorkflowDefinition {
  nodes: WorkflowNode[];
  edges: WorkflowEdge[];
  [key: string]: unknown;
}

export function getExecutionOrder(definition: unknown): string[] {
  if (!definition || typeof definition !== 'object')
    throw new Error('Workflow definition is invalid');
  const graph = definition as Partial<WorkflowDefinition>;
  if (!Array.isArray(graph.edges) || graph.edges.length === 0)
    throw new Error('Workflow definition must contain a non-empty edge chain');
  if (!Array.isArray(graph.nodes))
    throw new Error('Workflow definition must contain nodes');
  const order = [graph.edges[0].source];
  for (let index = 0; index < graph.edges.length; index += 1) {
    const edge = graph.edges[index];
    if (
      !edge ||
      typeof edge.source !== 'string' ||
      typeof edge.target !== 'string' ||
      (index > 0 && edge.source !== graph.edges[index - 1].target)
    ) {
      throw new Error('Workflow edges must form a single directed chain');
    }
    order.push(edge.target);
  }
  const nodesById = new Map(graph.nodes.map((node) => [node.id, node]));
  for (const id of order) {
    if (typeof id !== 'string' || !nodesById.has(id))
      throw new Error(`Workflow edge references missing node: ${String(id)}`);
  }
  return order;
}
import { INodeExecutor } from '../../domain/entities/node-executor';
import { NodeKeys } from '../../domain/constants/execution.constants';

export class ManualTriggerExecutor implements INodeExecutor<
  Record<string, never>,
  null,
  null
> {
  readonly key = NodeKeys.TRIGGER_MANUAL;

  parseConfig(): Record<string, never> {
    return {};
  }

  parseInput(): null {
    return null;
  }

  execute(): Promise<null> {
    return Promise.resolve(null);
  }
}
import { z } from 'zod';
import { google } from 'googleapis';
import { INodeExecutor } from '../../domain/entities/node-executor';
import { NodeKeys } from '../../domain/constants/execution.constants';

const ConfigSchema = z.object({
  credential_id: z.string().min(1),
  spreadsheet_id: z.string().min(1),
  sheet_name: z.string().min(1),
});

export type GoogleSheetReadRowsConfig = z.infer<typeof ConfigSchema>;

const InputSchema = z.null();

export interface GoogleSheetsValuesResponse {
  data: {
    values?: unknown[][];
  };
}

const CredentialSchema = z
  .object({
    refresh_token: <REDACTED>,
  })
  .passthrough();

export interface GoogleSheetsClient {
  spreadsheets: {
    values: {
      get: (params: {
        spreadsheetId: string;
        range: string;
      }) => Promise<GoogleSheetsValuesResponse>;
    };
  };
}

export type SheetsClientFactory = (credential: {
  refresh_token: <REDACTED>;
}) => GoogleSheetsClient;

export class GoogleSheetReadRowsExecutor implements INodeExecutor<
  GoogleSheetReadRowsConfig,
  null,
  Array<Record<string, unknown>>
> {
  readonly key = NodeKeys.GOOGLE_SHEET_READ_ROWS;
  readonly configSchema = ConfigSchema;
  readonly inputSchema = InputSchema;
  readonly credentialSchema = CredentialSchema;

  constructor(
    private readonly sheetsClientFactory: SheetsClientFactory = (
      credential,
    ) => {
      const auth = new google.auth.OAuth2(
        process.env['google-Client-Id'],
        process.env['google-Client-secret'],
      );
      auth.setCredentials({
        refresh_token: <REDACTED>,
      });
      return google.sheets({
        version: 'v4',
        auth,
      }) as unknown as GoogleSheetsClient;
    },
  ) {}

  parseConfig(raw: unknown): GoogleSheetReadRowsConfig {
    return this.configSchema.parse(raw);
  }

  parseInput(raw: unknown): null {
    return this.inputSchema.parse(raw);
  }

  parseCredential(raw: unknown) {
    return this.credentialSchema.parse(raw);
  }

  async execute(params: {
    config: GoogleSheetReadRowsConfig;
    input: null;
    credential: unknown;
  }): Promise<Array<Record<string, unknown>>> {
    if (params.input !== null) {
      throw new Error('Google Sheets input must be null');
    }

    const googleCredential = this.parseCredential(params.credential);
    try {
      const sheets = this.sheetsClientFactory(googleCredential);
      const response = await sheets.spreadsheets.values.get({
        spreadsheetId: params.config.spreadsheet_id,
        range: params.config.sheet_name,
      });

      const rows = response.data.values ?? [];

      if (rows.length === 0) {
        return [];
      }

      const [headerRow, ...dataRows] = rows;
      const headers = headerRow.map((header) => String(header));

      return dataRows.map((row) => {
        const item: Record<string, unknown> = {};
        headers.forEach((header, index) => {
          item[header] = row[index] ?? '';
        });
        return item;
      });
    } catch (error) {
      const message =
        error instanceof Error ? error.message : 'Google Sheets read failed';
      throw new Error(
        message.replace(
          /(access_token|refresh_token|token|Bearer <REDACTED>
          '[REDACTED]',
        ),
      );
    }
  }
}
import { ExecutionStatus } from '../constants/execution.constants';
import {
  WorkflowVersionForExecution,
  ExecutionRecord,
  NodeLogRecord,
} from '../models/execution.types';

export abstract class ExecutionRepository {
  abstract findVersion(id: string): Promise<WorkflowVersionForExecution | null>;
  abstract createExecution(input: Omit<ExecutionRecord, 'id'>): Promise<string>;
  abstract resolveCredential(
    credentialId: string,
    ownerId: string,
  ): Promise<unknown>;
  abstract saveNodeLog(executionId: string, log: NodeLogRecord): Promise<void>;
  abstract finishExecution(
    id: string,
    status: ExecutionStatus,
    finishedAt: Date,
    durationMs: number,
  ): Promise<void>;
  abstract findExecutionResult(id: string): Promise<unknown>;
}

