import { Module } from '@nestjs/common';
import { CqrsModule } from '@nestjs/cqrs';
import { PrismaModule } from '@app/database';
import { AuthModule } from '@app/auth';
import { NodeTypesController } from './presentation/http/node-types.controller';
import { GetNodeTypesHandler } from './application/queries/get-node-types.query';
import { NodeTypeDefinitionRepository } from './domain/repositories/node-type-definition.repository';
import { PrismaNodeTypeDefinitionRepository } from './infrastructure/persistence/prisma-node-type-definition.repository';

const QueryHandlers = [GetNodeTypesHandler];

const Repositories = [
  {
    provide: NodeTypeDefinitionRepository,
    useClass: PrismaNodeTypeDefinitionRepository,
  },
];

@Module({
  imports: [CqrsModule, PrismaModule, AuthModule],
  controllers: [NodeTypesController],
  providers: [...QueryHandlers, ...Repositories],
  exports: [...Repositories],
})
export class NodeLibraryModule {}
import { NodeTypeDefinition } from '../entities/node-type-definition.entity';

export abstract class NodeTypeDefinitionRepository {
  abstract findAllActive(): Promise<NodeTypeDefinition[]>;
}
import { Injectable } from '@nestjs/common';
import { PrismaService } from '@app/database';
import { NodeTypeDefinitionRepository } from '../../domain/repositories/node-type-definition.repository';
import { NodeTypeDefinition } from '../../domain/entities/node-type-definition.entity';
import { NodeTypeDefinitionMapper } from './mappers/node-type-definition.mapper';

@Injectable()
export class PrismaNodeTypeDefinitionRepository implements NodeTypeDefinitionRepository {
  constructor(private readonly prisma: PrismaService) {}

  async findAllActive(): Promise<NodeTypeDefinition[]> {
    const nodeTypes = await this.prisma.nodeTypeDefinition.findMany({
      where: {
        isActive: true,
      },
      orderBy: [{ category: 'asc' }, { displayName: 'asc' }],
    });

    return nodeTypes.map((row) => NodeTypeDefinitionMapper.toDomain(row));
  }
}
import { NodeCategory } from '../enums/node-category.enum';

export class NodeTypeDefinition {
  constructor(
    public readonly id: string,
    public readonly key: string,
    public readonly displayName: string,
    public readonly category: NodeCategory,
    public readonly configSchema: unknown,
    public readonly isActive: boolean,
    public readonly icon?: string | null,
    public readonly color?: string | null,
    public readonly description?: string | null,
    public readonly inputSchema?: unknown,
    public readonly outputSchema?: unknown,
    public readonly connectorId?: string | null,
    public readonly createdAt?: Date,
    public readonly updatedAt?: Date,
  ) {}
}
