import { NodeReferenceError, PairedItemError } from '../expression/errors';
import { ExpressionContext } from '../expression/template';
import { Item, ItemJson } from '../models/item';

export interface NodeRun {
  nodeId: string;
  nodeName: string;
  input: Item[];
  output: Item[];
}

// node display name -> ids of the nodes carrying that name
export type NodeNameIndex = ReadonlyMap<string, readonly string[]>;

export function buildNodeNameIndex(
  nodes: ReadonlyArray<{ id: string; data?: { name?: unknown } }>,
): NodeNameIndex {
  const index = new Map<string, string[]>();
  for (const node of nodes) {
    const name = node.data?.name;
    if (typeof name !== 'string' || name.length === 0) continue;
    index.set(name, [...(index.get(name) ?? []), node.id]);
  }
  return index;
}

function findRunIndex(
  runs: readonly NodeRun[],
  names: NodeNameIndex,
  nodeName: string,
): number {
  const ids = names.get(nodeName);
  if (!ids || ids.length === 0) {
    throw new NodeReferenceError(
      `Node "${nodeName}" was not found - it may have been renamed`,
    );
  }
  if (ids.length > 1) {
    throw new NodeReferenceError(
      `Node name "${nodeName}" is used by ${ids.length} nodes; rename them so the reference is unambiguous`,
    );
  }
  const runIndex = runs.findIndex((run) => run.nodeId === ids[0]);
  if (runIndex === -1) {
    throw new NodeReferenceError(
      `Node "${nodeName}" has not run before this node`,
    );
  }
  return runIndex;
}

// `runs` are the nodes that already ran, in order; the node being executed
// received `runs[last].output` as input. `currentIndex` is the position of the
// current item in that input.
export function createExpressionContext(params: {
  runs: readonly NodeRun[];
  names: NodeNameIndex;
  currentItem: Item;
  currentIndex: number;
}): ExpressionContext {
  const { runs, names, currentItem, currentIndex } = params;

  return {
    currentItem,

    getNodeAll(nodeName: string): ItemJson[] {
      return runs[findRunIndex(runs, names, nodeName)].output.map(
        (item) => item.json,
      );
    },

    getPairedJson(nodeName: string): ItemJson {
      const targetPos = findRunIndex(runs, names, nodeName);
      let index = currentIndex;
      for (let pos = runs.length - 1; pos >= targetPos; pos -= 1) {
        const item = runs[pos].output[index];
        if (item === undefined) {
          throw new PairedItemError(
            `There is no item to pair with node "${nodeName}"`,
          );
        }
        if (pos === targetPos) return item.json;
        if (item.pairedItem === undefined) {
          throw new PairedItemError(
            `Cannot tell which item of node "${nodeName}" matches the current item. Use $node["${nodeName}"].all to read all of its items`,
          );
        }
        index = item.pairedItem;
      }
      throw new PairedItemError(
        `There is no item to pair with node "${nodeName}"`,
      );
    },
  };
}

import { ExpressionSyntaxError } from './errors';
import { parseExpression } from './parser';
import { readField } from './path';
import { applySchemaDefaults, resolveConfig } from './resolve-config';
import { evaluateTemplate, ExpressionContext, parseTemplate } from './template';

const ctx = (json: Record<string, unknown>): ExpressionContext => ({
  currentItem: { json },
  getNodeAll: () => [],
  getPairedJson: () => ({}),
});

const evaluate = (template: string, json: Record<string, unknown>): unknown =>
  evaluateTemplate(parseTemplate(template), ctx(json));

describe('parseExpression', () => {
  it.each([
    ['$json.name', { root: 'json', path: [{ kind: 'key', name: 'name' }] }],
    [
      '$json.a.b[0]',
      {
        root: 'json',
        path: [
          { kind: 'key', name: 'a' },
          { kind: 'key', name: 'b' },
          { kind: 'index', index: 0 },
        ],
      },
    ],
    [
      '$json["full name"]',
      { root: 'json', path: [{ kind: 'key', name: 'full name' }] },
    ],
    ['$json', { root: 'json', path: [] }],
    ['  name  ', { root: 'json', path: [{ kind: 'key', name: 'name' }] }],
    [
      '$node["Read Customers"].json.email',
      {
        root: 'node',
        nodeName: 'Read Customers',
        access: 'json',
        path: [{ kind: 'key', name: 'email' }],
      },
    ],
    [
      "$node['Sheet'].all[0].id",
      {
        root: 'node',
        nodeName: 'Sheet',
        access: 'all',
        path: [
          { kind: 'index', index: 0 },
          { kind: 'key', name: 'id' },
        ],
      },
    ],
  ])('parses %s', (source, expected) => {
    expect(parseExpression(source)).toEqual(expected);
  });

  it.each([
    '$json.',
    '$json..a',
    '$json[abc]',
    '$json[0',
    '$node.json',
    '$node["X"].items',
    '$node["X"',
    '$foo',
    '1 + 1',
    'a b',
    '',
  ])('rejects %p', (source) => {
    expect(() => parseExpression(source)).toThrow(ExpressionSyntaxError);
  });
});

describe('evaluateTemplate', () => {
  const json = {
    name: 'An',
    amount: 5000000,
    paid: false,
    tags: ['a', 'b'],
    customer: { city: 'Hue' },
    nothing: null,
  };

  it('keeps the type when the field is a single expression', () => {
    expect(evaluate('{{$json.amount}}', json)).toBe(5000000);
    expect(evaluate('{{$json.paid}}', json)).toBe(false);
    expect(evaluate('{{$json.tags}}', json)).toEqual(['a', 'b']);
    expect(evaluate('{{$json.customer}}', json)).toEqual({ city: 'Hue' });
  });

  it('returns null for a single expression that does not exist', () => {
    expect(evaluate('{{$json.missing}}', json)).toBeNull();
    expect(evaluate('{{$json.nothing}}', json)).toBeNull();
  });

  it('concatenates into a string when mixed with text', () => {
    expect(evaluate('Hello {{$json.name}}!', json)).toBe('Hello An!');
    expect(evaluate('No: {{$json.amount}}d', json)).toBe('No: 5000000d');
    expect(evaluate('{{$json.name}}{{$json.amount}}', json)).toBe('An5000000');
  });

  it('serialises objects and renders missing values as empty text', () => {
    expect(evaluate('c={{$json.customer}}', json)).toBe('c={"city":"Hue"}');
    expect(evaluate('x={{$json.missing}}.', json)).toBe('x=.');
    expect(evaluate('x={{$json.nothing}}.', json)).toBe('x=.');
  });

  it('supports the legacy bare name and spaces inside braces', () => {
    expect(evaluate('Welcome, {{name}}!', json)).toBe('Welcome, An!');
    expect(evaluate('Welcome, {{ name }}!', json)).toBe('Welcome, An!');
  });

  it('reads nested paths and array indexes', () => {
    expect(evaluate('{{$json.customer.city}}', json)).toBe('Hue');
    expect(evaluate('{{$json.tags[1]}}', json)).toBe('b');
  });

  it('does not reach prototype members', () => {
    expect(evaluate('{{$json.constructor}}', json)).toBeNull();
    expect(evaluate('{{$json.__proto__}}', json)).toBeNull();
  });

  it('keeps text without a complete expression as is', () => {
    expect(evaluate('plain', json)).toBe('plain');
    expect(evaluate('open {{ only', json)).toBe('open {{ only');
  });

  it('throws on invalid syntax', () => {
    expect(() => parseTemplate('{{$json.}}')).toThrow(ExpressionSyntaxError);
  });
});

describe('readField', () => {
  const json = { status: 'new', 'Full Name': 'An', data: { label: 'urgent' } };

  it('reads simple, dotted and verbatim keys', () => {
    expect(readField(json, 'status')).toBe('new');
    expect(readField(json, 'data.label')).toBe('urgent');
    expect(readField(json, 'Full Name')).toBe('An');
  });

