  getConfigSchemas(): Promise<Map<string, unknown>> {
    return Promise.resolve(
      new Map<string, unknown>([
        [NodeKeys.TRIGGER_MANUAL, MANUAL_TRIGGER_CONFIG_SCHEMA],
