import type { ReactNode } from 'react';
import { Label } from '@/components/ui/label';

interface FieldShellProps {
  id: string;
  label: string;
  expression?: boolean;
  hint?: ReactNode;
  children: ReactNode;
}

// Label, optional "fx" marker (the field accepts expressions) and hint around a control.
export function FieldShell({ id, label, expression, hint, children }: FieldShellProps) {
  return (
    <div className="space-y-1.5">
      <div className="flex items-center justify-between">
        <Label htmlFor={id} className="capitalize">
          {label}
        </Label>
        {expression && (
          <span className="rounded border border-purple-200 bg-purple-100 px-1.5 py-0.5 font-mono text-[10px] text-purple-700">
            fx
          </span>
        )}
      </div>
      {children}
      {hint && <p className="text-[11px] text-muted-foreground">{hint}</p>}
    </div>
  );
}

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { FieldShell } from './FieldShell';

interface EnumFieldProps {
  id: string;
  label: string;
  options: string[];
  value: string;
  onChange: (value: string) => void;
}

export function EnumField({ id, label, options, value, onChange }: EnumFieldProps) {
  return (
    <FieldShell id={id} label={label}>
      <Select
        value={value || null}
        onValueChange={(next) => next !== null && onChange(next)}
        items={options.map((option) => ({ value: option, label: option }))}
      >
        <SelectTrigger id={id} className="w-full">
          <SelectValue placeholder={`Select ${label.toLowerCase()}`} />
        </SelectTrigger>
        <SelectContent>
          {options.map((option) => (
            <SelectItem key={option} value={option}>
              {option}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </FieldShell>
  );
}

import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { FieldShell } from './FieldShell';

interface TextFieldProps {
  id: string;
  label: string;
  value: string;
  onChange: (value: string) => void;
  multiline?: boolean;
  expression?: boolean;
  placeholder?: string;
}

export function TextField({
  id,
  label,
  value,
  onChange,
  multiline,
  expression,
  placeholder,
}: TextFieldProps) {
  const hint = expression
    ? 'Use {{$json.column}} or {{$node["Node name"].json.column}}'
    : undefined;

  return (
    <FieldShell id={id} label={label} expression={expression} hint={hint}>
      {multiline ? (
        <Textarea
          id={id}
          value={value}
          rows={5}
          placeholder={placeholder}
          onChange={(e) => onChange(e.target.value)}
        />
      ) : (
        <Input
          id={id}
          value={value}
          placeholder={placeholder ?? (expression ? '{{$json.field}}' : `Enter ${label.toLowerCase()}`)}
          onChange={(e) => onChange(e.target.value)}
        />
      )}
    </FieldShell>
  );
}

import { Input } from '@/components/ui/input';
import { parseNumberInput } from '../../utils/node-config';
import { FieldShell } from './FieldShell';

interface NumberFieldProps {
  id: string;
  label: string;
  value: number | undefined;
  onChange: (value: number | undefined) => void;
  integer?: boolean;
  min?: number;
}

// Stores a real number (or nothing when the box is emptied), never the text typed.
export function NumberField({ id, label, value, onChange, integer, min }: NumberFieldProps) {
  return (
    <FieldShell id={id} label={label}>
      <Input
        id={id}
        type="number"
        inputMode={integer ? 'numeric' : 'decimal'}
        step={integer ? 1 : 'any'}
        min={min}
        value={value ?? ''}
        onChange={(e) => onChange(parseNumberInput(e.target.value))}
      />
    </FieldShell>
  );
}

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useSaveApiKeyCredential } from '../hooks/useCredentials';

interface AddApiKeyDialogProps {
  connectorKey: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSaved: (credentialId: string) => void;
}

export function AddApiKeyDialog({
  connectorKey,
  open,
  onOpenChange,
  onSaved,
}: AddApiKeyDialogProps) {
  const [name, setName] = useState('');
  const [apiKey, setApiKey] = useState('');
  const save = useSaveApiKeyCredential();

  const canSave = name.trim() !== '' && apiKey.trim() !== '' && !save.isPending;

  const handleOpenChange = (next: boolean) => {
    if (!next) {
      setName('');
      setApiKey('');
      save.reset();
    }
    onOpenChange(next);
  };

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    if (!canSave) return;
    save.mutate(
      { connectorKey, name, apiKey },
      {
        onSuccess: (saved) => {
          onSaved(saved.id);
          handleOpenChange(false);
        },
      },
    );
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent>
        <form onSubmit={handleSubmit} className="grid gap-4">
          <DialogHeader>
            <DialogTitle>Add API key for {connectorKey}</DialogTitle>
            <DialogDescription>
              The key is stored encrypted and is never shown again.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-1.5">
            <Label htmlFor="api-key-name">Name</Label>
            <Input
              id="api-key-name"
              value={name}
              placeholder="e.g. Personal key"
              onChange={(e) => setName(e.target.value)}
            />
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="api-key-value">API key</Label>
            <Input
              id="api-key-value"
              type="password"
              autoComplete="off"
              value={apiKey}
              onChange={(e) => setApiKey(e.target.value)}
            />
          </div>

          {save.isError && (
            <p className="text-xs text-destructive">
              Could not save the key. Check the values and try again.
            </p>
          )}

          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => handleOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={!canSave}>
              {save.isPending ? 'Saving...' : 'Save'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { useCredentials } from '../../hooks/useCredentials';
import { AddApiKeyDialog } from '../AddApiKeyDialog';
import { FieldShell } from './FieldShell';

interface CredentialPickerProps {
  id: string;
  label: string;
  // Provider chosen in another field of the node; undefined until it is picked.
  connectorKey: string | undefined;
  value: string;
  onChange: (credentialId: string) => void;
}

// Lists only the credentials of the chosen connector and lets the user save a new API key.
export function CredentialPicker({
  id,
  label,
  connectorKey,
  value,
  onChange,
}: CredentialPickerProps) {
  const [dialogOpen, setDialogOpen] = useState(false);
  const { data: credentials = [], isLoading } = useCredentials(connectorKey);

  // A selection that no longer exists (e.g. another provider's) shows as empty.
  const selected = credentials.some((c) => c.id === value) ? value : null;

  return (
    <FieldShell
      id={id}
      label={label}
      hint={connectorKey ? undefined : 'Choose a provider first'}
    >
      <Select
        value={selected}
        onValueChange={(next) => next !== null && onChange(next)}
        disabled={!connectorKey}
        items={credentials.map((c) => ({ value: c.id, label: c.name }))}
      >
        <SelectTrigger id={id} className="w-full">
          <SelectValue
            placeholder={
              isLoading
                ? 'Loading...'
                : credentials.length === 0
                  ? 'No saved keys yet'
                  : 'Select a key'
            }
          />
        </SelectTrigger>
        <SelectContent>
          {credentials.map((credential) => (
            <SelectItem key={credential.id} value={credential.id}>
              {credential.name}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      {connectorKey && (
        <>
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="w-full"
            onClick={() => setDialogOpen(true)}
          >
            + Add API key
          </Button>
          <AddApiKeyDialog
            connectorKey={connectorKey}
            open={dialogOpen}
            onOpenChange={setDialogOpen}
            onSaved={onChange}
          />
        </>
      )}
    </FieldShell>
  );
}

interface OAuthFieldProps {
  id: string;
  label: string;
  connectorName: string;
  connected: boolean;
  onConnect: () => void;
}

// Credentials of OAuth connectors (Google) come from a pop-up sign-in, not a form.
export function OAuthField({ id, label, connectorName, connected, onConnect }: OAuthFieldProps) {
  return (
    <FieldShell id={id} label={label}>
      <Button type="button" variant="outline" className="w-full" onClick={onConnect}>
        Connect {connectorName}
      </Button>
      {connected && <p className="text-xs text-green-600">✓ Connected</p>}
    </FieldShell>
  );
}

