          <span className="rounded border border-purple-200 bg-purple-100 px-1.5 py-0.5 font-mono text-[10px] text-purple-700">
            fx
          </span>
        )}
      </div>
      {children}
      {hint && <p className="text-[11px] text-muted-foreground">{hint}</p>}
    </div>
  );
}

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { FieldShell } from './FieldShell';

interface EnumFieldProps {
  id: string;
  label: string;
  options: string[];
  value: string;
  onChange: (value: string) => void;
}

export function EnumField({ id, label, options, value, onChange }: EnumFieldProps) {
  return (
    <FieldShell id={id} label={label}>
      <Select
        value={value || null}
        onValueChange={(next) => next !== null && onChange(next)}
        items={options.map((option) => ({ value: option, label: option }))}
      >
        <SelectTrigger id={id} className="w-full">
          <SelectValue placeholder={`Select ${label.toLowerCase()}`} />
        </SelectTrigger>
        <SelectContent>
          {options.map((option) => (
            <SelectItem key={option} value={option}>
              {option}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </FieldShell>
  );
}

import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { FieldShell } from './FieldShell';

interface TextFieldProps {
  id: string;
  label: string;
  value: string;
  onChange: (value: string) => void;
  multiline?: boolean;
  expression?: boolean;
  placeholder?: string;
}

export function TextField({
  id,
  label,
  value,
  onChange,
  multiline,
  expression,
  placeholder,
}: TextFieldProps) {
  const hint = expression
    ? 'Use {{$json.column}} or {{$node["Node name"].json.column}}'
    : undefined;

  return (
    <FieldShell id={id} label={label} expression={expression} hint={hint}>
      {multiline ? (
        <Textarea
          id={id}
          value={value}
          rows={5}
          placeholder={placeholder}
          onChange={(e) => onChange(e.target.value)}
        />
      ) : (
        <Input
          id={id}
          value={value}
          placeholder={placeholder ?? (expression ? '{{$json.field}}' : `Enter ${label.toLowerCase()}`)}
          onChange={(e) => onChange(e.target.value)}
        />
      )}
    </FieldShell>
  );
}

import { Input } from '@/components/ui/input';
import { parseNumberInput } from '../../utils/node-config';
import { FieldShell } from './FieldShell';

interface NumberFieldProps {
  id: string;
  label: string;
  value: number | undefined;
  onChange: (value: number | undefined) => void;
  integer?: boolean;
  min?: number;
}

// Stores a real number (or nothing when the box is emptied), never the text typed.
export function NumberField({ id, label, value, onChange, integer, min }: NumberFieldProps) {
  return (
    <FieldShell id={id} label={label}>
      <Input
        id={id}
        type="number"
        inputMode={integer ? 'numeric' : 'decimal'}
        step={integer ? 1 : 'any'}
        min={min}
        value={value ?? ''}
        onChange={(e) => onChange(parseNumberInput(e.target.value))}
