  dependentKeys,
  getDefaultConfig,
  parseNumberInput,
  placeholderFor,
  propertyTitle,
} from 'file:///D:/New%20folder/workflow-automation/frontend/src/features/workflow/utils/node-config.ts';

const schema = {
  properties: {
    provider: { type: 'string', enum: ['a', 'b'] },
    credential_id: { 'x-connectorKeyFrom': 'provider' },
    other_cred: { 'x-connectorKeyFrom': 'something_else' },
    model: {
