    },
    max_tokens: { type: 'integer', default: 1024 },
    output_format: { default: 'text' },
  },
};

assert.deepEqual(dependentKeys(schema, 'provider'), ['credential_id']);
assert.deepEqual(dependentKeys(schema, 'model'), []);
assert.deepEqual(dependentKeys(undefined, 'provider'), []);

const model = schema.properties.model;
assert.equal(placeholderFor(model, { provider: 'a' }), 'e.g. m-a');
assert.equal(placeholderFor(model, { provider: 'b' }), 'e.g. m-b');
assert.equal(placeholderFor(model, { provider: 'zzz' }), undefined);
assert.equal(placeholderFor(model, {}), undefined);
assert.equal(placeholderFor({ title: 'x' }, { provider: 'a' }), undefined);

assert.equal(parseNumberInput(''), undefined);
assert.equal(parseNumberInput('  '), undefined);
assert.equal(parseNumberInput('12'), 12);
assert.equal(parseNumberInput('0.5'), 0.5);
assert.equal(parseNumberInput('0'), 0);
assert.equal(parseNumberInput('abc'), undefined);

assert.equal(propertyTitle('max_tokens', {}), 'max tokens');
assert.equal(propertyTitle('model', model), 'Model');

// A new LLM node starts with the schema defaults only.
assert.deepEqual(getDefaultConfig(schema), { max_tokens: 1024, output_format: 'text' });

console.log('frontend helpers OK');

