import { chromium } from 'playwright-core';

const API = 'http://localhost:8081';
const APP = 'http://localhost:5173';
const SHOTS = new URL('./shots/', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1');
import fs from 'node:fs';
fs.mkdirSync(SHOTS, { recursive: true });

const results = [];
const check = (name, ok, detail = '') => {
  results.push({ name, ok });
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? '  -> ' + detail : ''}`);
};

async function step(name, fn) {
  try {
    await fn();
  } catch (error) {
    check(name, false, String(error.message).split('\n')[0]);
  }
}

// --- sign in through the real API, then hand the tokens to the app as it would store them
const login = await fetch(`${API}/api/auth/login`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ email: 'ui-test@flowpilot.local', password: <REDACTED> }),
});
const loginBody = await login.json();
const tokens = loginBody.data ?? loginBody;
const accessToken = <REDACTED> ?? tokens.access_token ?? tokens.token;
const refreshToken = <REDACTED> ?? tokens.refresh_token;
check('login via API', login.ok && !!accessToken, `status ${login.status}`);
if (!accessToken) {
  console.log(JSON.stringify(loginBody).slice(0, 300));
  process.exit(1);
}

const headers = { 'Content-Type': 'application/json', Authorization: `Bearer <REDACTED>` };
const created = await (await fetch(`${API}/api/workflows`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ name: 'UI TEST llm node' }),
})).json();
const workflowId = created.data.id;
console.log('workflow', workflowId);

const browser = await chromium.launch({ channel: 'msedge', headless: true });
const context = await browser.newContext({ viewport: { width: 1500, height: 900 } });
await context.addInitScript(
  ([t, r, u]) => {
    localStorage.setItem('flowpilot_token', t);
    localStorage.setItem('flowpilot_refresh_token', r ?? '');
    localStorage.setItem('flowpilot_user', JSON.stringify(u));
  },
  [accessToken, refreshToken, tokens.user ?? { id: '99999999-9999-4999-8999-999999999999', email: 'ui-test@flowpilot.local', name: 'UI Tester' }],
);
const page = await context.newPage();
