assert.deepEqual(keys({ 'x-propertyOrder': 'nope', properties: scrambled }), ['to', 'body', 'subject', 'credential_id']);
assert.deepEqual(keys(undefined), []);
assert.deepEqual(keys({}), []);
console.log('orderedProperties OK');

