const key = randomBytes(32);
function enc(text) { const iv = randomBytes(12); const c = createCipheriv('aes-256-gcm', key, iv); let e = c.update(text, 'utf8', 'hex'); e += c.final('hex'); return `${iv.toString('hex')}:${c.getAuthTag().toString('hex')}:${e}`; }
function dec(s) { const [iv, tag, data] = s.split(':'); const d = createDecipheriv('aes-256-gcm', key, Buffer.from(iv, 'hex')); d.setAuthTag(Buffer.from(tag, 'hex')); return d.update(data, 'hex', 'utf8') + d.final('utf8'); }
