for (let i = 0; i < 5000; i++) {
  const e = enc('test');
  if (e.slice(0, -1) + '0' === e) oldIdentical++;
  const last = e.slice(-1), t = e.slice(0, -1) + (last === '0' ? '1' : '0');
  if (t === e) newIdentical++;
  try { dec(t); } catch { newThrew++; }
}
