    ['-5', LlmLimits.DEFAULT_MAX_ITEMS_CEILING],
    ['1.5', LlmLimits.DEFAULT_MAX_ITEMS_CEILING],
  ])('reads %p as %p', (raw, expected) => {
    expect(parseMaxItemsCeiling(raw)).toBe(expected);
  });
});
