1	import { useCallback, useMemo, useRef } from 'react';
2	import {
3	  ReactFlow,
4	  Background,
5	  Controls,
6	  MiniMap,
7	  addEdge,
8	  useReactFlow,
9	  ReactFlowProvider,
10	} from '@xyflow/react';
11	import type {
12	  Node,
13	  Edge,
14	  OnNodesChange,
15	  OnEdgesChange,
16	  OnConnect,
17	  NodeTypes,
18	} from '@xyflow/react';
19	import '@xyflow/react/dist/style.css';
20	
21	import { TriggerNode } from './nodes/TriggerNode';
22	import { ActionNode } from './nodes/ActionNode';
23	import { useDesignerStore } from '../store/designer.store';
24	import { getDefaultConfig, uniqueNodeName } from '../utils/node-config';
25	
26	interface CanvasProps {
27	  nodes: Node[];
28	  edges: Edge[];
29	  onNodesChange: OnNodesChange;
30	  onEdgesChange: OnEdgesChange;
31	  setNodes: React.Dispatch<React.SetStateAction<Node[]>>;
32	  setEdges: React.Dispatch<React.SetStateAction<Edge[]>>;
33	}
34	
35	function CanvasContent({ nodes, edges, onNodesChange, onEdgesChange, setNodes, setEdges }: CanvasProps) {
36	  const reactFlowWrapper = useRef<HTMLDivElement>(null);
37	  const { screenToFlowPosition } = useReactFlow();
38	  const setSelectedNodeId = useDesignerStore((state) => state.setSelectedNodeId);
39	  const catalogNodeTypes = useDesignerStore((state) => state.nodeTypes);
40	
41	  const nodeTypes = useMemo<NodeTypes>(() => {
42	    const map: NodeTypes = {
43	      default: ActionNode,
44	      triggerNode: TriggerNode,
45	      actionNode: ActionNode,
46	      'trigger.manual': TriggerNode,
47	      'logic.filter': ActionNode,
48	      'integration.gmail.send': ActionNode,
49	      'integration.slack.post_message': ActionNode,
50	    };
51	
52	    if (Array.isArray(catalogNodeTypes)) {
53	      for (const nt of catalogNodeTypes) {
54	        if (nt.category === 'TRIGGER' || nt.key.startsWith('trigger.')) {
55	          map[nt.key] = TriggerNode;
56	        } else {
57	          map[nt.key] = ActionNode;
58	        }
59	      }
60	    }
61	    return map;
62	  }, [catalogNodeTypes]);
63	
64	  const onConnect: OnConnect = useCallback(
65	    (connection) => setEdges((eds) => addEdge(connection, eds)),
66	    [setEdges]
67	  );
68	
69	  const onDragOver = useCallback((event: React.DragEvent) => {
70	    event.preventDefault();
71	    event.dataTransfer.dropEffect = 'move';
72	  }, []);
73	
74	  const onDrop = useCallback(
75	    (event: React.DragEvent) => {
76	      event.preventDefault();
77	
78	      const type = event.dataTransfer.getData('application/reactflow/type');
79	      const name = event.dataTransfer.getData('application/reactflow/name');
80	      const key = event.dataTransfer.getData('application/reactflow/key');
81	
82	      if (!type) return;
83	
84	      const position = screenToFlowPosition({
85	        x: event.clientX,
86	        y: event.clientY,
87	      });
88	
89	      const catalogNode = Array.isArray(catalogNodeTypes)
90	        ? catalogNodeTypes.find((nt) => nt.key === key)
91	        : undefined;
92	
93	      setNodes((nds) => {
94	        const newNode: Node = {
95	          id: `${type}-${Date.now()}`,
96	          type,
97	          position,
98	          data: {
99	            name: uniqueNodeName(
100	              name,
101	              nds.map((node) => String(node.data?.name ?? '')),
102	            ),
103	            key,
104	            config: getDefaultConfig(catalogNode?.configSchema),
105	          },
106	        };
107	        return nds.concat(newNode);
108	      });
109	    },
110	    [screenToFlowPosition, setNodes, catalogNodeTypes]
111	  );
112	
113	  return (
114	    <div className="flex-1 h-full w-full bg-gray-50 relative" ref={reactFlowWrapper}>
115	      <ReactFlow
116	        nodes={nodes}
117	        edges={edges}
118	        onNodesChange={onNodesChange}
119	        onEdgesChange={onEdgesChange}
120	        onConnect={onConnect}
121	        onDrop={onDrop}
122	        onDragOver={onDragOver}
123	        nodeTypes={nodeTypes}
124	        onSelectionChange={(params) => {
125	          if (params.nodes.length > 0) {
126	            setSelectedNodeId(params.nodes[0].id);
127	          } else {
128	            setSelectedNodeId(null);
129	          }
130	        }}
131	        fitView
132	      >
133	        <Background color="#ccc" gap={16} />
134	        <Controls />
135	        <MiniMap zoomable pannable />
136	      </ReactFlow>
137	    </div>
138	  );
139	}
140	
141	export function Canvas(props: CanvasProps) {
142	  return (
143	    <ReactFlowProvider>
144	      <CanvasContent {...props} />
145	    </ReactFlowProvider>
146	  );
147	}
